"use strict";(globalThis.webpackChunkmythogen_engine_blog=globalThis.webpackChunkmythogen_engine_blog||[]).push([[5718],{3233(e,n,t){t.r(n),t.d(n,{assets:()=>h,contentTitle:()=>a,default:()=>d,frontMatter:()=>o,metadata:()=>r,toc:()=>l});var s=t(4848),i=t(8453);const o={},a="Part II: The Bill \u2014 Who Is Paying for the Story",r={id:"AI_TAO/ch03",title:"Part II: The Bill \u2014 Who Is Paying for the Story",description:"Narratives are not free. Keeping a story running takes real money \u2014 and the most ingenious part is: those who pay often do not know they are paying.",source:"@site/i18n/en/docusaurus-plugin-content-docs/current/AI_TAO/ch03.md",sourceDirName:"AI_TAO",slug:"/AI_TAO/ch03",permalink:"/en/docs/AI_TAO/ch03",draft:!1,unlisted:!1,tags:[],version:"current",frontMatter:{},sidebar:"docs",previous:{title:"Chapter 2: Game Over \u2014 The Cross-Border Entanglement of Microsoft and Sega",permalink:"/en/docs/AI_TAO/ch02"},next:{title:'Chapter 4: AI Narrative Economics \u2014 When "Replacement" Becomes a Business',permalink:"/en/docs/AI_TAO/ch04"}},h={},l=[{value:"A Straight Line Drawn from the Wrong Starting Point",id:"a-straight-line-drawn-from-the-wrong-starting-point",level:2},{value:"The Real Source of Funding",id:"the-real-source-of-funding",level:2},{value:"AI Has Not Yet Paid Its Own Way",id:"ai-has-not-yet-paid-its-own-way",level:2},{value:"Get the Causality Wrong, and Every Judgement Is Wrong",id:"get-the-causality-wrong-and-every-judgement-is-wrong",level:2},{value:"The Fourth Scenario Anthropic Did Not Discuss",id:"the-fourth-scenario-anthropic-did-not-discuss",level:2}];function c(e){const n={em:"em",h1:"h1",h2:"h2",header:"header",hr:"hr",img:"img",p:"p",strong:"strong",...(0,i.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(n.header,{children:(0,s.jsx)(n.h1,{id:"part-ii-the-bill--who-is-paying-for-the-story",children:"Part II: The Bill \u2014 Who Is Paying for the Story"})}),"\n",(0,s.jsx)(n.p,{children:"Narratives are not free. Keeping a story running takes real money \u2014 and the most ingenious part is: those who pay often do not know they are paying."}),"\n",(0,s.jsx)(n.p,{children:'This part traces four bills. Chapter 3 traces AI\'s electricity bill: the machine that claims to "write itself" \u2014 whose pockets does the fuel come from? Chapter 4 traces the human-resources bill: beneath the story of "AI replacing humans," who gets laid off to make the numbers work? Chapter 5 traces the most concealed bill of all: how your attention and judgement are spent as currency \u2014 and when you try to speak up about it, how the narrative rights themselves press it back down. Chapter 6 dismantles a technical bill: a landmine buried at the deepest layer of chip architecture \u2014 who paid the tuition, who took the diploma, and who is still stepping on it.'}),"\n",(0,s.jsx)(n.p,{children:"The figures used in this part are all 2026 evidence. The evidence will expire \u2014 in six months, some of these numbers will start to loosen \u2014 but the fingerprints on the evidence will not. The mechanism is the fingerprint."}),"\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.img,{alt:"Gemini_Generated_Image_vzvnemvzvnemvzvn.png",src:t(2665).A+"",width:"1200",height:"654"})}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h1,{id:"chapter-3-ai-begins-writing-itself--but-who-is-paying-the-power-bill",children:"Chapter 3: AI Begins Writing Itself \u2014 But Who Is Paying the Power Bill?"}),"\n",(0,s.jsx)(n.p,{children:"In the spring of 2026, a twenty-six-year-old game engineer was laid off."}),"\n",(0,s.jsx)(n.p,{children:"The studio he worked at was owned by Microsoft, making first-person shooters. The layoff letter's wording was standard: \"Realigning resources to match the company's strategic priorities.\" Translated into plain language: your salary was redirected to buy NVIDIA GPUs for building AI data centres."}),"\n",(0,s.jsx)(n.p,{children:"He went home, opened Steam, and glanced at his PC. Inside the chassis sat an RTX 4070 Ti \u2014 purchased last year for close to NT$20,000. He knew the card contained Tensor Cores, hardware NVIDIA had designed for AI computation. He had no use for them. He bought the card to play games."}),"\n",(0,s.jsx)(n.p,{children:'But a portion of the money he paid had subsidised NVIDIA\'s R&D costs for AI computation hardware. And NVIDIA used the fruits of that R&D to produce the H100, which it sold to Microsoft. Microsoft used H100s to build AI data centres. Then Microsoft laid him off, because the AI data centre was more "strategically prioritised" than his studio.'}),"\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"He subsidised the R&D of his own gravedigger."})}),"\n",(0,s.jsx)(n.p,{children:"This is not a sob story. It is a causal chain. And this causal chain is precisely the one that every mainstream AI report gets wrong."}),"\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.img,{alt:"Gemini_Generated_Image_kxrm5gkxrm5gkxrm.png",src:t(7851).A+"",width:"1200",height:"654"})}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"a-straight-line-drawn-from-the-wrong-starting-point",children:"A Straight Line Drawn from the Wrong Starting Point"}),"\n",(0,s.jsx)(n.p,{children:'In June 2026, Anthropic published an article titled "When AI builds itself." The numbers were startling: as of May, over 80% of the code Anthropic merged into its products was written by Claude; the same engineer\'s quarterly output was eight times what it was in 2024; the length of tasks AI could reliably complete was doubling every four months.'}),"\n",(0,s.jsx)(n.p,{children:"These numbers are not bluster. AI really is writing itself. Even with human oversight on review and direction-setting, the boundary of AI's technical capability is expanding at an unprecedented pace \u2014 this is a fact, and denying it will only cost you your capacity for judgement."}),"\n",(0,s.jsx)(n.p,{children:"Taiwan's tech circles were excited. Some wrote analyses concluding that Taiwan was the beneficiary: if AI truly enters recursive self-improvement, compute is the only bottleneck, and the bottleneck on compute is TSMC's CoWoS \u2014 Taiwan's chips would be amplified in value."}),"\n",(0,s.jsxs)(n.p,{children:["This judgement is not wrong in itself. But like all mainstream coverage, it makes a leap at one point \u2014 ",(0,s.jsx)(n.strong,{children:"equating the acceleration of technical capability with the closure of the commercial loop."})]}),"\n",(0,s.jsx)(n.p,{children:'AI is getting stronger \u2014 no question. But "getting stronger" and "being able to pay its own electricity bill" are two different things. An engine can spin faster and faster, but if the petrol comes from someone else\'s tank, no amount of RPM changes one fact \u2014 it does not have its own oil well.'}),"\n",(0,s.jsx)(n.p,{children:"Open any AI investment report, and the logic is the same straight line: AI demand explodes \u2192 companies scramble for compute \u2192 NVIDIA sells cards \u2192 TSMC prints money \u2192 more compute \u2192 AI gets stronger \u2192 demand grows further. A self-reinforcing cycle. A perpetual motion machine. Technology is accelerating, so the funding chain will automatically close."}),"\n",(0,s.jsx)(n.p,{children:'If that "so" holds, AI development can be sustained indefinitely. Investors can rest easy.'}),"\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:'That "so" is wrong.'})}),"\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.img,{alt:"Gemini_Generated_Image_rmuenxrmuenxrmue.png",src:t(5960).A+"",width:"1200",height:"669"})}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"the-real-source-of-funding",children:"The Real Source of Funding"}),"\n",(0,s.jsx)(n.p,{children:"In 2006, NVIDIA released the GeForce 8800 GTX. Gamers saw a leap in visual quality. What they did not see: the card's streaming processors had been redesigned \u2014 they could now compute not just pixels, but anything. Seven months later, NVIDIA launched CUDA Toolkit 1.0. No gamer noticed. But part of the $599 they paid was used to subsidise the R&D cost of general-purpose compute cores."}),"\n",(0,s.jsxs)(n.p,{children:["In Chapter 7 of ",(0,s.jsx)(n.em,{children:"Game Over"}),", I called this mechanism the ",(0,s.jsx)(n.strong,{children:'"R&D Tax"'})," \u2014 gamers, without their knowledge, paid ten years of parallel-computing R&D costs for NVIDIA, until 2012, when AlexNet used two gaming GPUs to ignite the deep learning revolution."]}),"\n",(0,s.jsx)(n.p,{children:"Chapter 8 traced another thread on the hardware side: gaming GPU large-die orders forced TSMC to push large-die yields to the limit; once yields matured, the same production lines were repurposed to produce AI chips. Long-term console SoC orders filled off-season capacity, providing stable cash flow for investment in the next-generation node."}),"\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"CUDA's software ecosystem, TSMC's large-die processes, and wafer fab utilisation rates \u2014 all of it was paved with gamers' money up front, with AI moving in behind them."})}),"\n",(0,s.jsx)(n.p,{children:"Some might say: that is ancient history. NVIDIA in 2026 has data centre revenue of $193.7 billion; gaming is down to $16 billion, less than eight percent. AI no longer needs gaming."}),"\n",(0,s.jsx)(n.p,{children:"Really? Did AI earn that $193.7 billion itself?"}),"\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.img,{alt:"Gemini_Generated_Image_tb56a7tb56a7tb56.png",src:t(8130).A+"",width:"1200",height:"669"})}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"ai-has-not-yet-paid-its-own-way",children:"AI Has Not Yet Paid Its Own Way"}),"\n",(0,s.jsx)(n.p,{children:"Trace where that $193.7 billion goes. Who are NVIDIA's data centre customers? Microsoft, Google, Meta, Amazon, and the tech companies and sovereign wealth funds behind them."}),"\n",(0,s.jsx)(n.p,{children:"Where does their money come from?"}),"\n",(0,s.jsxs)(n.p,{children:["In 2026, OpenAI is projected to lose $14 billion, on revenue of approximately $13 billion \u2014 ",(0,s.jsx)(n.strong,{children:"for every dollar earned, more than two are spent."})," Cumulative losses are expected to swell to $44 billion before profitability is reached. The money it uses to buy GPUs comes primarily from Microsoft's investment and Azure compute credits."]}),"\n",(0,s.jsx)(n.p,{children:"What about Microsoft? Capital expenditure in 2026 is projected to reach $190 billion. This money is not earned back by AI products \u2014 it is Office 365 subscription fees, Windows licence fees, and LinkedIn advertising revenue paying AI's bill."}),"\n",(0,s.jsx)(n.p,{children:"What about Google? Capital expenditure in 2025 jumped from $29 billion to $75 billion. Where does the money come from? Search ads. YouTube ads. Google Cloud enterprise subscriptions. Not Gemini's profits."}),"\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"At no link in the entire chain is AI paying its own way."})}),"\n",(0,s.jsxs)(n.p,{children:["This is not just a matter of financial statements. Pull the perspective back from Silicon Valley to Taiwan, open any tech-community discussion thread, and ask the simplest question: ",(0,s.jsx)(n.strong,{children:"Do you know anyone around you who has actually made money from AI?"})]}),"\n",(0,s.jsx)(n.p,{children:'In June 2026, a Taiwanese tech KOL posted a single line on Facebook: "So far, 90% of the people I\'ve seen actually monetise AI are doing it by selling courses." Beneath it, dozens of replies were variations of the same answer \u2014 someone said they saved two assistants\' salaries, someone said they improved back-office efficiency, someone said they built an internal tool so colleagues would stop asking the same questions. Saving time, cutting costs, boosting efficiency. But when pressed with "Does that count as monetisation?", even the original poster shook his head: "Improving efficiency \u2014 I don\'t think that counts as monetisation."'}),"\n",(0,s.jsxs)(n.p,{children:["The most cutting comment was a single sentence: ",(0,s.jsx)(n.strong,{children:'"The only way ordinary people are actually making money from AI is by buying NVIDIA and TSMC stock. Everything else is bullshit."'})]}),"\n",(0,s.jsxs)(n.p,{children:["This sentence unwittingly articulated the entire structure: AI's \"monetisation\" is not happening on the user side \u2014 it is not end-users creating new revenue models with AI. It is happening on AI's ",(0,s.jsx)(n.strong,{children:"supply-chain side"})," \u2014 NVIDIA's and TSMC's stock prices. And what is the foundation of those stock prices? Twenty years of gamers' R&D tax, plus capital expenditure piled up from the non-AI business profits of tech giants."]}),"\n",(0,s.jsx)(n.p,{children:'Macro level: OpenAI spends more than two dollars for every dollar it earns. Micro level: Taiwan\'s own tech circles are asking, "Other than selling courses, who is actually making money from AI?" Evidence at two scales points to the same conclusion.'}),"\n",(0,s.jsxs)(n.p,{children:["The funding source has shifted from gamers to Office subscriptions and search ads, but the essence has not changed: ",(0,s.jsx)(n.strong,{children:"AI is a machine running on someone else's fuel. It has never been a perpetual motion machine."})]}),"\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.img,{alt:"Gemini_Generated_Image_mjndmgmjndmgmjnd.png",src:t(9058).A+"",width:"1200",height:"654"})}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"get-the-causality-wrong-and-every-judgement-is-wrong",children:"Get the Causality Wrong, and Every Judgement Is Wrong"}),"\n",(0,s.jsx)(n.p,{children:'This is the real core of the problem. Not "gamers have it rough" \u2014 that is an emotional judgement. The problem is:'}),"\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:'If you reverse the causality, your assessment of "how long this AI arms race can last" will be built on a false premise.'})}),"\n",(0,s.jsx)(n.p,{children:"The mainstream narrative says: AI demand \u2192 funding \u2192 development \u2192 more demand. Loop closed. Sustainable."}),"\n",(0,s.jsxs)(n.p,{children:["The real logic is: gamers' R&D tax (historical stock) + tech giants' non-AI business profits (current-period subsidy) \u2192 AI development. ",(0,s.jsx)(n.strong,{children:"The loop has not closed."})]}),"\n",(0,s.jsx)(n.p,{children:"If the loop has not closed, the sustainability of this game depends on two external conditions \u2014 and both conditions are narrowing."}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"First, the gaming side."})," The RTX 5090's MSRP jumped from the previous generation's $1,599 to $1,999, with street prices consistently above $3,000. Gamers' wallets are not infinite. Meanwhile, Microsoft and Sony are dismantling the very stress-testing ground that is gaming \u2014 shutting down Tango Gameworks, Arkane Austin, Japan Studio, Bluepoint, and redirecting resources to AI and live-service games. The conclusion from Chapter 10 of ",(0,s.jsx)(n.em,{children:"Game Over"}),": the owners of the stress-testing ground are tearing up their own foundations with their own hands."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Second, the cross-subsidy side."})," If AI's commercial returns keep failing to materialise, and the tech giants' non-AI businesses start being eroded by AI itself \u2014 search ads siphoned off by AI Q&A, Office replaced by free AI tools \u2014 then the source of the cross-subsidy will dry up too. AI is eroding not only other people's businesses but also the very businesses that sustain it."]}),"\n",(0,s.jsx)(n.p,{children:"Both lines are narrowing simultaneously."}),"\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.img,{alt:"Gemini_Generated_Image_e4m3cwe4m3cwe4m3.png",src:t(9650).A+"",width:"1200",height:"654"})}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"the-fourth-scenario-anthropic-did-not-discuss",children:"The Fourth Scenario Anthropic Did Not Discuss"}),"\n",(0,s.jsx)(n.p,{children:"Anthropic's article depicted three futures: AI improvement decelerates, AI improves steadily, AI enters full recursive self-improvement. Analysts in Taiwan pointed to the compute leverage. These discussions all have value."}),"\n",(0,s.jsxs)(n.p,{children:["But they all skipped a more fundamental question: ",(0,s.jsx)(n.strong,{children:'Who is paying the electricity bill for this machine that "writes itself"?'})]}),"\n",(0,s.jsx)(n.p,{children:'If the answer is "AI itself," then recursive self-improvement can be sustained. All three scenarios deserve serious consideration.'}),"\n",(0,s.jsx)(n.p,{children:"If the answer is \"gamers' R&D tax plus tech giants' non-AI business profits\" \u2014 and both sources are narrowing \u2014 then you need to consider a fourth scenario that Anthropic's article did not discuss:"}),"\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"The machine has learned to write itself. But it can no longer afford the electricity bill."})}),"\n",(0,s.jsx)(n.p,{children:"Not because there is not enough compute. Not because TSMC's CoWoS is insufficient. But because the external fuels sustaining this machine \u2014 gamers' spending power, Office subscription fees, search advertising revenue \u2014 are simultaneously being hollowed out by the machine itself."}),"\n",(0,s.jsx)(n.p,{children:"The causal chain is not a straight line. It is a spiral. And the direction of the spiral is reversing."}),"\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.img,{alt:"Gemini_Generated_Image_qm0rtvqm0rtvqm0r.png",src:t(941).A+"",width:"1200",height:"654"})}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.p,{children:'The next time you read an AI investment report that says "AI demand drives compute growth," cross out the words "AI demand." Replace them with "gamers\' R&D tax plus Office subscription profits." Then re-read the report and see whether its conclusion still holds.'}),"\n",(0,s.jsx)(n.p,{children:"Most likely, it will not."}),"\n",(0,s.jsx)(n.p,{children:"As for that twenty-six-year-old engineer \u2014 his RTX 4070 Ti is still slotted into his chassis. Every time he boots up and the fans spin, he is playing games made by the industry he was laid off from, on hardware whose R&D he helped fund."}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"The power bill's source has been traced. But AI's bills are more than one. The next one is issued by the HR department \u2014 and the name on the invoice is, ironically, \"AI\" itself."})})]})}function d(e={}){const{wrapper:n}={...(0,i.R)(),...e.components};return n?(0,s.jsx)(n,{...e,children:(0,s.jsx)(c,{...e})}):c(e)}},9650(e,n,t){t.d(n,{A:()=>s});const s=t.p+"assets/images/Gemini_Generated_Image_e4m3cwe4m3cwe4m3-af491334f988c2a00d551e8b50afafb9.jpg"},7851(e,n,t){t.d(n,{A:()=>s});const s=t.p+"assets/images/Gemini_Generated_Image_kxrm5gkxrm5gkxrm-fed6e3adaba4c6e2f3cbd542dc17ab81.jpg"},9058(e,n,t){t.d(n,{A:()=>s});const s=t.p+"assets/images/Gemini_Generated_Image_mjndmgmjndmgmjnd-769bca00051b0f2284468cf609eaa15d.jpg"},941(e,n,t){t.d(n,{A:()=>s});const s=t.p+"assets/images/Gemini_Generated_Image_qm0rtvqm0rtvqm0r-515a617ba74f1bcfe65466fc49c57df8.jpg"},5960(e,n,t){t.d(n,{A:()=>s});const s=t.p+"assets/images/Gemini_Generated_Image_rmuenxrmuenxrmue-ea1c3fb38ff194359e439bba6867241e.jpg"},8130(e,n,t){t.d(n,{A:()=>s});const s=t.p+"assets/images/Gemini_Generated_Image_tb56a7tb56a7tb56-711bdf36f43d162fbab8f15b6eb2acde.jpg"},2665(e,n,t){t.d(n,{A:()=>s});const s=t.p+"assets/images/Gemini_Generated_Image_vzvnemvzvnemvzvn-cb2da0ebb6b2fa071e33255a6baafcd3.jpg"},8453(e,n,t){t.d(n,{R:()=>a,x:()=>r});var s=t(6540);const i={},o=s.createContext(i);function a(e){const n=s.useContext(o);return s.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:a(e.components),s.createElement(o.Provider,{value:n},e.children)}}}]);